        b, st2 = first_def_grade(r); trans[(r['status'] == 'pass', st2 == 'pass')] += 1
        cls_[classify(r)] += 1
    print(name, 'first-def regrade (cur,new):', dict(trans), '| outcome classes:', dict(cls_))
print('edit multi-</think>:', sum(r['text'].count('</think>') >= 2 for r in g8e), '| orig:', sum(r['text'].count('</think>') >= 2 for r in g8o))
for r in g8e:
    if r['status'] == 'no_code':
        a = after_think(r['text']); print('no_code', r['id'], r['sample'], 'n</think>', r['text'].count('</think>'), 'ans_len', len(a), 'fences', a.count(FENCE), repr(a[-120:].replace('\n', '\\n').encode('ascii', 'replace').decode()))
O8 = {(r['id'], r['sample']): r for r in g8o}
for r in g8e:
    ro = O8[(r['id'], r['sample'])]
    if ro['status'] == 'pass' and r['status'] != 'pass':
        print('pass->fail', r['id'], r['sample'], r['status'], r.get('exc'), 'len', r['n_tokens'], 'n</think>', r['text'].count('</think>'), '| orig len', ro['n_tokens'])
